        transaction.tokenAddress,
        ethers.parseEther(transaction.amount),
        toChainConfig.chainId,
        transaction.recipient,
        {
          value: bridgeFee,
          gasLimit: transaction.gasLimit || '500000'
        }
      );

      await tx.wait();
      return tx.hash;

