      image: data.image || data.image_url || '',
      owner: data.owner,
      creator: data.creator,
      price: data.price,
      currency: data.currency,
      blockchain: data.blockchain,
      metadata: data.metadata || {},
      createdAt: new Date(data.created_at),
      updatedAt: new Date(data.updated_at),
    };
  }
