            const gasPrice = await this.getOptimalGasPrice();

            // Execute swap transaction
            const tx = await router.swapExactTokensForTokens(
                amountIn,
                amountOutMin,
                path,
                recipient,
                deadline,
                {
                    gasLimit,
                    gasPrice
                }
            );

            console.log(`Swap transaction submitted: ${tx.hash}`);

