                                     (!this.config.enableBalanceCheck || validationResult.checks.balance);

            // Cache result
            this._setCache(cacheKey, validationResult);

            return validationResult;

        } catch (error) {
            console.error('Wallet validation error:', error);
            return {
                address,
                network,
                isValid: false,
                error: error.message,
                timestamp: new Date().toISOString()
            };
        }
