            console.log('Exchange rates:', rates);

        } catch (error) {
            if (error instanceof InnWalletsAPIError) {
                console.error(`API Error: ${error.message} (Code: ${error.errorCode})`);
            } else {
                console.error(`Unexpected error: ${error.message}`);
            }
        }
    })();
}
