        this.apiSecret = config.apiSecret;
        this.baseUrl = config.baseUrl || 'https://api.belgacoin.com/v1';
        this.testnet = config.testnet || false;

        if (!this.apiKey || !this.apiSecret) {
            throw new Error('API key and secret are required');
        }
