        $error = curl_error($curl);

        curl_close($curl);

        if ($response === false) {
            throw new Exception("cURL error: " . $error);
        }

        if ($httpCode >= 400) {
            throw new Exception("HTTP error: " . $httpCode);
        }

        return $response;
    }
