     */
    private function validateConfig(array $config): array
    {
        $required = ['db_host', 'db_name', 'db_user', 'db_pass', 'site_url', 'admin_user', 'admin_pass', 'admin_email'];

        foreach ($required as $key) {
            if (empty($config[$key])) {
