    <div class="container">
        <div class="header">
            <h1>USAAllSMM Customer Reviews</h1>
            <p>Customer Satisfaction & Service Quality Analysis</p>
        </div>

        <div class="stats-grid" id="statsGrid">
            <!-- Stats will be loaded here -->
        </div>

        <div class="controls">
