        $this->baseUrl = $baseUrl ?? self::API_BASE_URL;
        $this->headers = [
            'Authorization: Bearer ' . $this->apiKey,
            'Content-Type: application/json',
            'Accept: application/json',
            'User-Agent: BankClaimsClient/1.0.0'
        ];
