      const params = {
        place_id: placeId,
        limit: options.limit || 50,
        sort_by: options.sortBy || 'newest',
        ...(options.minRating && { min_rating: options.minRating })
      };

      const response = await this.client.get('/google-maps/reviews', { params });
      return response.data;
